ee:message.ee:set-payload:
%dw 2.0 output application/json var customer = payload.businessCentralResponse.value[0] var Address = (customer.Address default "") var Address_2 = (customer.Address_2 default "") var address = Address as String ++ " " ++ Address_2 as String
--- { // --- Mappings based on BC 'No' field --- "organization_code": customer.No, // BC No (Customer Code) "client_code": "DEMO", // Set to temporary value "customer_code": customer.No, // BC No (Customer Code) "record_id": 0, // Source not specified, set to 0
// --- Direct Mappings --- "name": customer.Name, "alternative_name": customer.Name_2, "region": customer.City, "location": customer.Address_2, "category": customer.Customer_Posting_Group, "phone_number": customer.Phone_No, "email": customer.E_Mail, "vat_number": customer.VAT_Registration_No, "contact_person": customer.ContactName, "currency_code": customer.Currency_Code, "country_code": customer.Country_Region_Code, "payment_terms_code": customer.Payment_Terms_Code, "sales_rep_code": customer.Salesperson_Code, "credit_limit": customer.Credit_Limit_LCY default 0, "address":address , "account_status": (trim(customer.Blocked default "")) match { case "" -> "1" case "Ship" -> "0" case "Invoice" -> "0" case "All" -> "0" else -> "0" }, // If Blocked = “” then “1”, Else 0
// --- Unmapped/Fixed/Not Applicable Fields --- "accounts": null, "customer_warehouse": null, // Source ??? "pricelist_code": "", // Source ??? "latitude": 0.0, // Not Applicable "longitude": 0.0, // Not Applicable "postal_address": "", // Source Bill to / Ship to address? "transaction_status": null, "image": null, // Not Applicable "territory": "", // Source ??? "payment_mode": null, // Source ??? "discount_rate": "", // Source ??? "payment_terms_name": null, // Source not specified "route_code": null, // Source not specified "vat_except": null, // Source not specified "vat_hs_code": null, // Source not specified "customer_group": "" // Source not specified
}

