ee:message.ee:set-payload:
%dw 2.0 output application/json
var item = ((vars.businessCentralItemResponsevalue default [])[0]) default {} var itemUoms = vars.businessCentralItem_Units_of_MeasureResponsevalue default [] var uoms = vars.businessCentralUnits_of_MeasureResponsevalue default []
// Build UOM array for this item var joinedUoms = (itemUoms filter ((iu) -> iu.Item_No == item.No)) map ((iu) -> { // Add the new field here use_in_sale: item.Sales_Unit_Of_Measure == iu.Code, // find matching row in Units_of_Measure Item_UOM_Code: iu.Code, Qty_per_Unit_of_Measure: iu.Qty_per_Unit_of_Measure, Length: iu.Length, Width: iu.Width, Height: iu.Height, Weight: iu.Weight, Cubage: iu.Cubage, Efris_UOM : ((((uoms filter ((u) -> u.Code == iu.Code))[0]) default {}).Efris_UOM) default null, UOM_Description: ((((uoms filter ((u) -> u.Code == iu.Code))[0]) default {}).Description) default null, UOM_International_Standard_Code: ((((uoms filter ((u) -> u.Code == iu.Code))[0]) default {}).International_Standard_Code) default null })
--- { No: item.No default null, Vendor_Item_No: item.Vendor_Item_No default null, Description: item.Description default null, Item_Category_Code: item.Item_Category_Code default null, Search_Description: item.Search_Description default null, Tariff_No : item.Tariff_No default null, VAT_Prod_Posting_Group: item.VAT_Prod_Posting_Group default null, Tariff_No: item.Tariff_No default null, Blocked: item.Blocked default false, Commodity_Category : item.Commodity_Category, Base_Unit_of_Measure: item.Base_Unit_of_Measure,
uoms: joinedUoms }

%dw 2.0
output application/json

var item = payload

---
{
  //commented some to match from documentation
  organization_code: "SGUG",
  //principal_code: "PRIN004",
  //principal_name: "Principal Name",

  product_code: item.No,
  //manufacturer_code: item.Vendor_Item_No,
  product_name: item.Search_Description,
  category: item.Item_Category_Code,
  description: item.Description,
  tax_code: item.VAT_Prod_Posting_Group,
  hs_code : item.Tariff_No default null,
  commodity_category_id : item.Commodity_Category default null,
  status: (if (item.Blocked) 0 else 1) as String,
  //"type"  : "Item",
  //apply_discount: 1,

  uom_list: (item.uoms default []) map (u) -> {
      uom_code: u.Item_UOM_Code,
      uom_name: u.UOM_Description,
      uom_quantity: (u.Qty_per_Unit_of_Measure as String),
      length: (u.Length as String),
      width: (u.Width as String),
      height: (u.Height as String),
      weight: u.Weight,
      //volume: u.Cubage,
      //use_in_sale: u.use_in_sale,
      //weight_uom: "KG"    // SAT requires a fixed weight UOM string
	  //added below  from documentation
	  BaseQty: (u.Qty_per_Unit_of_Measure as String), 
      AltQty: "1.000000", 
	  is_default: if (u.Item_UOM_Code == item.Base_Unit_of_Measure) "1"
        else "0", 
      "tax_authority_uom": u.Efris_UOM

  }
}

