ee:message.ee:set-payload:
%dw 2.0
output application/json

// Define the two inputs from your Business Central responses
var receipts = vars.businessCentralTransfer_ReceiptResponsevalue default []
var lines = vars.businessCentralTransfer_Receipt_LinesResponsevalue default []
var orgCode = vars.bctargetCompany default "SGUG"

---
receipts map (receipt) -> {
    "doc_type": "stock_transfer",
    //"organization_code": orgCode,
    "organization_code": "SGUG",
    "erp_reference": receipt.Transfer_Order_No,
    "user_code": receipt.Transfer_to_Code default "-1",
    //"user_code": -1,
    "from_warehouse": receipt.Transfer_from_Code,
    "to_warehouse": receipt.Transfer_to_Code,
    "record_date": receipt.Posting_Date ,
    "record_id": receipt.EXT_Doc_Ref_No, 


    // Parentheses added around the filter operation to ensure it returns an Array for map
    "item_list": (lines filter (line) -> (line.Document_No == receipt.No)) map (item) -> {
        "item_code": item.Item_No,
        "item_quantity": item.Quantity,
        "uom_code": item.Unit_of_Measure_Code
    }
}

