ee:message.ee:set-payload:
%dw 2.0
output application/json
import * from dw::core::Arrays
//all price lists regardless of whether they are Active, Draft, or within the current date
// Variables from Business Central
var Item_Card_Excel = vars.businessCentralItemResponsevalue default []
var Sales_Prices_Excel_Line = vars.businessCentralSales_Prices_LineResponsevalue default []
var Sales_Prices_Excel = vars.businessCentralSales_PriceResponsevalue default []

// 1. Get ALL Headers (No longer filtering for Active or Date)
var allHeaders = Sales_Prices_Excel 

// 2. Map all lines and headers for performance
var headerMap = allHeaders groupBy $.Code
var allLinesMap = Sales_Prices_Excel_Line groupBy $.Product_No

---
(Item_Card_Excel flatMap ((item) -> do {
    var masterPrice = item.Unit_Price default 0

    // A. Generate the MASTER record (Baseline defaults)
    var masterRecord = {
        "Sales_Type": "MASTER",
        "Sales_Code": "MASTER",
        "Status": "Active",
        "StartingDate": "0001-01-01",
        "EndingDate": "0001-01-01",
        "Description": item.Description,
        "No": item."No",
        //"Unit_of_Measure_Code": item.Base_Unit_of_Measure,
        "Sales_Unit_of_Measure": item.Sales_Unit_of_Measure default item.Base_Unit_of_Measure,
        "Unit_Cost": item.Unit_Cost,
        "Unit_Price": masterPrice
    }

    // B. Get all price list lines for this item (Unfiltered)
    var matchedLines = allLinesMap[item."No"] default []

    var specificPriceRecords = matchedLines map ((line) -> do {
        // Look up the header for THIS specific line to get real Dates and Status
        var header = headerMap[line.Price_List_Code][0] default {}
        ---
        {
            "Sales_Type": header.SourceType default "",
            "Sales_Code": header.Code default "",
            "Status": header.Status default "UNKNOWN",
            "StartingDate": header.StartingDate default "0001-01-01",
            "EndingDate": header.EndingDate default "0001-01-01",
            "Description": item.Description,
            "No": item."No",
            //"Unit_of_Measure_Code": line.Unit_of_Measure_Code default item.Base_Unit_of_Measure,
            //"Sales_Unit_of_Measure": item.Sales_Unit_of_Measure,
            "Sales_Unit_of_Measure": line.Unit_of_Measure_Code default item.Base_Unit_of_Measure,
            "Unit_Cost": item.Unit_Cost,
            "Unit_Price": line.Unit_Price default 0
        }
    })
    ---
    // Combine Master + all specific records (Drafts, Expired, and Active) without filter out zero prices
    [masterRecord] ++ specificPriceRecords 
})) as Array<Object> 
orderBy ((item) -> item.No ++ item.Sales_Code)

