ee:message.ee:set-payload:
%dw 2.0 output application/json import * from dw::core::Arrays
// Extracting values from variables var itemAvail = vars.businessCentralItem_Avail_by_LocationResponsevalue default [] var itemCard = vars.businessCentralItemResponsevalue default [] var locations = vars.businessCentralLocationsResponsevalue default []
--- /* 1. First, we join Availability with Item Master using 'No'. 2. Second, we join that result with Locations using 'Location_Code'. */ leftJoin( leftJoin(itemAvail, itemCard, (avail) -> avail.No, (card) -> card.No), locations, (combined) -> combined.l.Location_Code, (loc) -> loc.Code ) map (result) -> { "Location_Code": result.l.l.Location_Code, // result.r is the Location master match "Location_Name": result.r.Name default "", "Registered_Location_Code": result.r.Code default "", // result.l.r is the Item Card match "Item_Description": result.l.r.Description default "", "Item_No": result.l.l.No, "Unit_of_Measure": result.l.r.Base_Unit_of_Measure default "", "Remaining_Quantity": result.l.l.Remaining_Quantity }

%dw 2.0
output application/json
import * from dw::core::Numbers

var totalRecords = vars.totalRecords
var lastPage = ceil(totalRecords / vars.per_page)
var apiBaseUrl = "https://" ++ p('erp.solutech.exp.api') ++ "/api/Stock_Balance"
var target = "2"
var action = vars.action default "GET"
var data = payload

---
{
    "data": {
        // Defines the primary warehouse context for this response
        "warehouse_code": (data[0].Location_Code default ""), 
        "warehouse_balances": data map (item) -> {
        "warehouse_code": item.Location_Code default "",
        "warehouse_name": item.Location_Name default "",
         //"location_id": item.Location_Code default "",
            "product_name": item.Item_Description default "", 
            "product_code": item.Item_No default "",
            "quantity": item.Remaining_Quantity as Number,
            "uom_code": item.Unit_of_Measure default ""
            //"expected_date": "2024-11-30 11:20:54", //Hardcoded
            //"expected_quantity": 0, //Hardcoded
            //"update_time": now() as String {format: "yyyy-MM-dd HH:mm:ss"} 
        }
    },
    "pagination": {
        "current_page": vars.page as String, 
        "per_page": vars.per_page as String, 
        "total": totalRecords as String, 
        "last_page": lastPage, 
        "next_page_url": if (vars.page < lastPage) 
                            apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=" ++ (vars.page + 1) ++ "&per_page=" ++ vars.per_page 
                         else null, 
        "prev_page_url": if (vars.page > 1) 
                            apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=" ++ (vars.page - 1) ++ "&per_page=" ++ vars.per_page 
                         else null, 
        "first_page_url": apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=1&per_page=" ++ vars.per_page,
        "last_page_url": apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=" ++ lastPage ++ "&per_page=" ++ vars.per_page
    }
}

