ee:message.ee:set-payload:
//output includes every customer in the dataset, even those with zero balances and no open invoices

%dw 2.0
output application/json
import * from dw::core::Numbers

// 1. Setup data sources from your flow variables
var customers = vars.businessCentralCustomersResponsevalue default []
var ledgerEntries = vars.businessCentralCustomer_Ledger_EntriesResponsevalue default []
var paymentTerms = vars.businessCentralPayment_TermsResponsevalue default []

// Flow control and environment variables
var orgCode = vars.bctargetCompany default "SGUGANDA"
var totalRecords = vars.totalRecords default 0
var lastPage = ceil(totalRecords / (vars.per_page default 1))
var apiBaseUrl = "https://" ++ p('erp.solutech.exp.api') ++ "/api/Customer_Account_Status"
var target = "2"
var action = vars.action default "GET"

// 2. Pre-process Ledger Entries for efficient lookup
// Group ALL entries by Customer for the SUM(Amount) calculation
var balanceGrouped = ledgerEntries groupBy $.Customer_No

// Filter for Open Invoices only and group them
var openInvoicesGrouped = (ledgerEntries filter ($.Document_Type == "Invoice" and ($.Open as String == "true"))) 
                            groupBy $.Customer_No

---
{
    "data": customers map (customer) -> {
        "customer_code": customer.No,
        // Formatting numbers to 6 decimal places as strings
        "credit_limit": (customer.Credit_Limit_LCY default 0) as String {format: "0.000000"},
        "payment_terms": customer.Payment_Terms_Code default "",

        // Summing Amount field from grouped ledger entries for the specific customer
        "customer_balance": (sum(balanceGrouped[customer.No].Amount default [0])) as String {format: "0.000000"},

        //"organization_code": upper(orgCode),
         "organization_code": "",
        "open_invoices": openInvoicesGrouped[customer.No] default [] map (invoice) -> {
            "erp_reference": invoice.Document_No,
            // Appending required timestamp suffix for SAT date parsing
            "doc_date": (invoice.Document_Date as String default "") ++ " 00:00:00.00000000",
            "doc_total": invoice.Amount default 0,
            "balance": invoice.Remaining_Amount default 0,
            //
            //"Document_Type": invoice.Document_Type,
            //"Open": invoice.Open,
        }
    },

    "pagination": {
        "current_page": vars.page as String, 
        "per_page": vars.per_page as String, 
        "total": totalRecords as String, 
        "last_page": lastPage, 
        "next_page_url": if (vars.page < lastPage) 
                            apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=" ++ (vars.page + 1) ++ "&per_page=" ++ vars.per_page 
                         else null, 
        "prev_page_url": if (vars.page > 1) 
                            apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=" ++ (vars.page - 1) ++ "&per_page=" ++ vars.per_page 
                         else null, 
        "first_page_url": apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=1&per_page=" ++ vars.per_page,
        "last_page_url": apiBaseUrl ++ "?TARGET=" ++ target ++ "&ACTION=" ++ action ++ "&page=" ++ lastPage ++ "&per_page=" ++ vars.per_page
    }
}

